<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>Events | Net-Works</title><style>*{box-sizing:border-box}body{margin:0;background:#f5f7fb;font:15px Arial;color:#18243a}header{background:#fff;border-bottom:1px solid #e2e8f0;padding:18px max(24px,calc((100% - 1120px)/2));font-size:23px;font-weight:800}.wrap{max-width:1120px;margin:42px auto;padding:0 20px}.intro{margin-bottom:25px}.intro h1{font-size:36px;margin:0 0 8px}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.card{background:#fff;border:1px solid #e1e7ef;border-radius:14px;overflow:hidden;box-shadow:0 8px 25px #1b2b4510}.cover{height:145px;background:linear-gradient(135deg,#377dff,#7756d8);display:flex;align-items:end;padding:18px;color:white}.body{padding:18px}.date{color:#377dff;text-transform:uppercase;font-size:12px;font-weight:800}.card h2{font-size:20px;margin:7px 0}.muted{color:#718096}.button{display:inline-block;background:#377dff;color:white;padding:10px 15px;border-radius:8px;text-decoration:none;margin-top:12px;font-weight:700}.pagination{display:flex;justify-content:flex-end;gap:0;margin:25px 0 0;padding:0;list-style:none}.page-link{display:block;min-width:38px;padding:9px 12px;border:1px solid #dce3ed;margin-left:-1px;background:#fff;color:#377dff;text-align:center;text-decoration:none}.page-item:first-child .page-link{border-radius:8px 0 0 8px}.page-item:last-child .page-link{border-radius:0 8px 8px 0}.page-item.active .page-link{position:relative;background:#377dff;color:#fff;border-color:#377dff}.page-item.disabled .page-link{color:#9aa5b5;background:#f3f5f8}@media(max-width:800px){.grid{grid-template-columns:1fr}}</style></head><body><header>Net-Works Events</header><main class="wrap"><div class="intro"><h1>Upcoming events</h1><div class="muted">Discover, reserve your seats and complete payment securely online.</div></div><div class="grid">@forelse($events as $event)<article class="card"><div class="cover"><b>{{$event->starts_at->format('d M Y')}}</b></div><div class="body"><div class="date">{{$event->starts_at->format('l, h:i A')}}</div><h2>{{$event->title}}</h2><div class="muted">{{$event->venue_name ?: 'Venue to be announced'}}</div><p>{{Str::limit($event->summary,100)}}</p><a class="button" href="{{route('events.show',$event)}}">View & register</a></div></article>@empty<div class="card body">No upcoming events are currently published.</div>@endforelse</div><div style="margin-top:25px">{{$events->links()}}</div></main></body></html>
